    "entries": [
      {
        "group": "Historische Persönlichkeiten des Hauses",
        "role": "Gründer",
        "name": "Morholt Pysgod",
        "description": "Gründete gemeinsam mit Caitrin Neidr das Pysgod-Kadettenhaus Tiwna. Die umstrittene Gründungserzählung verbindet ihre Hochzeit mit den wettstreitenden Geschenken der beiden Stammhäuser.",
        "imageKey": "haus-figur-1"
      },
      {
        "group": "Historische Persönlichkeiten des Hauses",
        "role": "Mitgründerin",
        "name": "Caitrin Neidr",
        "description": "Mitgründerin der Tiwna und Verbindung des neuen Hauses zu den Neidr. Der Gründungserzählung zufolge erhielt das Paar von ihrer Familie die alte Festung samt Fischerdorf.",
        "imageKey": "haus-figur-2"
      },
      {
        "group": "Historische Persönlichkeiten des Hauses",
        "role": "Historischer Baron",
        "name": "Caradoc Tiwna",
        "description": "Als frühes Oberhaupt des Hauses überliefert. Lebensdaten und genaue Amtszeit sind nicht bekannt.",
        "imageKey": "haus-figur-3"
      },
      {
        "group": "Historische Persönlichkeiten des Hauses",
        "role": "Historischer Baron",
        "name": "Brannock Tiwna",
        "description": "Führte das Haus bis 1683. Über individuelle Taten berichten die historischen Einträge keine näheren Einzelheiten.",
        "imageKey": "haus-figur-4"
      },
      {
        "group": "Historische Persönlichkeiten des Hauses",
        "role": "Historischer Baron",
        "name": "Efrawg Tiwna",
        "description": "Stand dem Haus von 1714 bis 1720 vor. Auf ihn folgte Morholt Tiwna.",
        "imageKey": "haus-figur-5"
      }
    ]
